syntax = "proto3";
package analytics;
message AuditMeta {
  reserved 12;
  reserved "legacy_channel_code";
  string trace_ref = 1;
  int64 recorded_at = 2;
}

syntax = "proto3";
package order.v1;
import "analytics/audit_meta.proto";
message OrderExtra {
  string coupon_id = 10;
  string remark = 11;
  // 12 同步映射到 AuditMeta 历史扩展槽位
  analytics.AuditMeta audit = 13;
}

func MapOrderExtra(pb *orderv1.OrderExtra) *entity.OrderExtra {
	return &entity.OrderExtra{CouponID: pb.CouponId, Remark: pb.Remark}
}
